    discoveryDiscover: {
        parameters: {
            query?: {
                /** @description Free text. §11.3 folds diacritics, so "kitab" matches "kitаb". */
                q?: string;
                /** @description Which of §6.1's states a campaign may be in. Repeat or comma-separate. */
                status?: ("upcoming" | "live" | "extended" | "successful")[];
                /** @description Category slugs. An open vocabulary: an unknown slug is an empty feed, not a 400, so a link shared after a rename still resolves. */
                category?: string[];
                /** @description Subcategory slugs, under the categories above. */
                subcategory?: string[];
                /** @description Tag slugs. */
                tag?: string[];
                /** @description Programme slugs — §4.3's editorial programmes. */
                programme?: string[];
                /** @description How close to its goal a campaign is. */
                completion?: ("under_25" | "25_to_50" | "50_to_75" | "75_to_100" | "over_100")[];
                /** @description A named goal range, as an alternative to goalMin and goalMax. */
                goalBand?: string;
                /** @description Lowest goal, as a decimal string. Money is never a query number either. */
                goalMin?: string;
                /** @description Highest goal, as a decimal string. */
                goalMax?: string;
                /** @description A named raised range, as an alternative to raisedMin and raisedMax. */
                raisedBand?: string;
                /** @description Least raised, as a decimal string. */
                raisedMin?: string;
                /** @description Most raised, as a decimal string. */
                raisedMax?: string;
                /** @description ISO country codes. */
                country?: string[];
                /** @description City slugs. */
                city?: string[];
                /** @description A point, as "lat,lon". Required when sort=near-me, which is why asking for that sort without it is refused rather than silently answered as newest. */
                near?: string;
                /** @description How far from `near` to look. */
                radiusKm?: string;
                /** @description Editorial and campaign qualifiers. */
                showOnly?: ("saved" | "recommended" | "featured")[];
                /** @description Ordering. §11.2 decides what each one means. */
                sort?: "newest" | "ending_soon" | "most_funded" | "most_backed" | "popularity" | "best_match" | "relevance" | "near_me";
                /** @description Page size. Bounded by the service; an out-of-range value is refused rather than clamped, so a client learns its request was not the one answered. */
                limit?: number;
                /** @description The `nextCursor` from the previous page. §10.3's cursor pagination: opaque, and never an offset. */
                cursor?: string;
            };
            header?: {
                "Accept-Language"?: string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description OK */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Feed"];
                };
            };
        };
    };
